const order=["思想","政治","科学","经济","艺术文化"];
let era=0, track="全部", q="";

const eraIndex=document.getElementById("eraIndex");
const introBand=document.getElementById("introBand");
const timeline=document.getElementById("timeline");
const detail=document.getElementById("detail");

function shortEraTitle(title){
  return title.replace(/^第.+?阶段：/,"");
}
function eraNo(i){ return String(i+1).padStart(2,"0"); }

function renderEraIndex(){
  eraIndex.innerHTML="";
  DATA.stages.forEach((s,i)=>{
    const b=document.createElement("button");
    b.type="button";
    b.className="era"+(i===era?" active":"");
    b.innerHTML=`<div class="num">${eraNo(i)}</div><div class="era-name">${shortEraTitle(s.title)}</div><div class="era-period">${s.period}</div>`;
    b.addEventListener("click",()=>{era=i; renderAll(); window.scrollTo({top:document.querySelector(".toolbar").getBoundingClientRect().top+window.scrollY-52,behavior:motionBehavior()});});
    eraIndex.appendChild(b);
  });
}

function matches(entry, t, s){
  if(track!=="全部" && t.norm!==track) return false;
  if(!q) return true;
  return (entry.name+" "+entry.body+" "+t.name+" "+s.title+" "+s.period).toLowerCase().includes(q.toLowerCase());
}

function renderIntro(){
  const s=DATA.stages[era];
  const cleanIntro=(s.intro||"").replace(/\*\*/g,"").replace(/\n+/g," ");
  introBand.innerHTML=`
    <div class="issue-no">${eraNo(era)}</div>
    <div class="issue-title">
      <div class="period">${s.period}</div>
      <h2>${shortEraTitle(s.title)}</h2>
    </div>
    <div class="issue-note">${cleanIntro || "这一时期的核心变化，需要放在五条文明主线上一起理解。"}</div>
  `;
}

function renderTimeline(){
  timeline.innerHTML="";
  const s=DATA.stages[era];
  let count=0;

  order.forEach(kind=>{
    if(track!=="全部" && track!==kind) return;
    const rows=s.tracks.filter(t=>t.norm===kind);
    const entries=[];
    rows.forEach(t=>t.entries.forEach(e=>{if(matches(e,t,s)) entries.push({e,t});}));

    if(!entries.length && q) return;

    const sec=document.createElement("section");
    sec.className="track";
    sec.dataset.kind=kind;
    sec.innerHTML=`
      <aside class="track-side">
        <div class="track-name">${kind}</div>
        <div class="track-count">${entries.length} entries</div>
      </aside>
      <div class="entries"></div>
    `;
    const box=sec.querySelector(".entries");

    entries.forEach(({e,t},idx)=>{
      count++;
      const b=document.createElement("button");
      b.type="button";
      b.className="entry";
      const work=e.work?`<div class="entry-work">${e.work}</div>`:"";
      b.innerHTML=`
        <span class="marker" aria-hidden="true"></span>
        <div class="entry-index">${eraNo(era)}.${String(idx+1).padStart(2,"0")}</div>
        <div class="entry-name">${e.name}</div>
        <div class="entry-summary">${e.summary || "点击展开完整资料。"}</div>
        ${work}
      `;
      b.addEventListener("click",()=>openDetail(e,t,s));
      box.appendChild(b);
    });
    timeline.appendChild(sec);
  });

  if(count===0){
    const empty=document.createElement("div");
    empty.className="atlas-empty";
    empty.textContent=`在当前时代没有找到“${q}”。试试切换时代，或换一个关键词。`;
    timeline.appendChild(empty);
  }
}

function openDetail(entry,t,s){
  const kws=(entry.keywords||[]).join(" · ");
  detail.className="detail open";
  detail.innerHTML=`
    <aside>
      <div class="detail-kicker">${t.norm}<br>${s.period}</div>
    </aside>
    <article class="detail-main">
      <h3>${entry.name}</h3>
      ${entry.detail_html}
    </article>
    <aside class="detail-aside">
      <div class="smallcap">Context</div>
      <div class="quote">${shortEraTitle(s.title)}</div>
      ${kws?`<div class="smallcap" style="margin-top:22px">Keywords</div><div class="quote">${kws}</div>`:""}
      <button type="button" class="close-detail">收起详情</button>
    </aside>
  `;
  detail.querySelector(".close-detail").addEventListener("click",()=>detail.classList.remove("open"));
  detail.scrollIntoView({behavior:motionBehavior(),block:"nearest"});
}

function renderChains(){
  const list=document.getElementById("chainList");
  list.innerHTML="";
  DATA.chains.forEach((c,i)=>{
    const b=document.createElement("button");
    b.type="button";
    b.className="chain-choice"+(i===0?" active":"");
    b.textContent=c.title;
    b.addEventListener("click",()=>{
      [...list.children].forEach(x=>x.classList.remove("active"));
      b.classList.add("active");
      showChain(c);
    });
    list.appendChild(b);
  });
  showChain(DATA.chains[0]);
}
function showChain(c){
  document.getElementById("chainTitle").textContent=c.title;
  document.getElementById("chainNote").textContent=c.note;
  document.getElementById("chainFlow").innerHTML=c.nodes.map((n,i)=>`<div class="chain-node">${n}</div>${i<c.nodes.length-1?'<div class="chain-arrow"></div>':''}`).join("");
}

function renderAll(){
  renderEraIndex();
  renderIntro();
  renderTimeline();
  detail.classList.remove("open");
}

document.getElementById("search").addEventListener("input",e=>{q=e.target.value.trim();renderTimeline();detail.classList.remove("open");});
document.getElementById("toolbarActions").addEventListener("click",e=>{
  const tb=e.target.closest("button[data-track]");
  if(!tb) return;
  track=tb.dataset.track;
  [...document.querySelectorAll("button[data-track]")].forEach(x=>x.classList.toggle("active",x===tb));
  renderTimeline();
  detail.classList.remove("open");
});

const mapBtn=document.getElementById("mapBtn"), readerBtn=document.getElementById("readerBtn");
mapBtn.addEventListener("click",()=>{
  document.getElementById("mapView").classList.remove("hidden");
  document.getElementById("readerView").classList.remove("active");
  mapBtn.classList.add("active");readerBtn.classList.remove("active");
});
readerBtn.addEventListener("click",()=>{
  document.getElementById("mapView").classList.add("hidden");
  document.getElementById("readerView").classList.add("active");
  readerBtn.classList.add("active");mapBtn.classList.remove("active");
});

renderAll();
renderChains();
